23	/// A production implementation of [`Scheduler`] that wraps a [`PlatformDispatcher`].
24	///
25	/// This allows GPUI to use the scheduler crate's executor types with the platform's
26	/// native dispatch mechanisms (e.g., Grand Central Dispatch on macOS).
27	pub struct PlatformScheduler {
28	    dispatcher: Arc<dyn PlatformDispatcher>,
29	    clock: Arc<PlatformClock>,
30	    next_session_id: AtomicU16,
31	    #[cfg(feature = "profiler")]
32	    foreground_runnables: crate::profiler::journal::ForegroundRunnableCounter,
33	}
34	
35	impl PlatformScheduler {
36	    pub fn new(dispatcher: Arc<dyn PlatformDispatcher>) -> Self {
37	        Self {
38	            dispatcher: dispatcher.clone(),
39	            clock: Arc::new(PlatformClock { dispatcher }),
40	            next_session_id: AtomicU16::new(0),
41	            #[cfg(feature = "profiler")]
42	            foreground_runnables: crate::profiler::journal::foreground_runnable_counter(),
43	        }
44	    }
